Protocol = Protocol or {}
Protocol.Serializer = Protocol.Serializer or {}
Protocol.Serializer.StringDefined = {}

function Protocol.Serializer.Config(rootdir)
	if rootdir:sub(-1) ~= '/' then
		rootdir = rootdir..'/'
	end
	require(rootdir..'_response-code')
require(rootdir..'')
end
